#!/usr/bin/env python3
"""MVP Gate Check: compute Spearman ρ across fractions/generations and judge PASS/CONDITIONAL."""

import argparse
import json
import os
import sys
import warnings
from pathlib import Path

import numpy as np
from scipy.stats import spearmanr

FRACTIONS = {"0pct": 0.0, "50pct": 0.5, "100pct": 1.0}
GENERATIONS = list(range(5))  # gen0-gen4

SIGNAL_FAMILIES = {
    "spectral": ["stable_rank", "spectral_entropy", "sv_ratio"],
    "output": ["token_entropy", "perplexity"],
    "downstream": ["hellaswag_acc"],
}

ALL_SIGNALS = [s for fam in SIGNAL_FAMILIES.values() for s in fam]

RHO_THRESHOLD = 0.7


def load_signals(output_dir: str) -> dict:
    """Load all signal files into {(frac_label, gen): {signal: value}}."""
    data = {}
    for frac_label in FRACTIONS:
        for gen in GENERATIONS:
            fname = f"signals_{frac_label}_gen{gen}.jsonl"
            fpath = os.path.join(output_dir, fname)
            if not os.path.exists(fpath):
                warnings.warn(f"Missing: {fname}")
                continue
            last_training_line = None
            with open(fpath) as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    rec = json.loads(line)
                    if rec.get("step", -1) == -1:
                        continue  # skip summary line
                    last_training_line = rec
            if last_training_line is None:
                warnings.warn(f"No training data in {fname}")
                continue
            rec = last_training_line
            signals = {}
            for key in ["stable_rank", "spectral_entropy", "token_entropy", "perplexity",
                         "training_loss", "gradient_norm", "hellaswag_acc"]:
                if key in rec:
                    signals[key] = rec[key]
            svs = rec.get("top_singular_values")
            if svs and len(svs) >= 2:
                signals["sv_ratio"] = svs[0] / svs[-1]
            data[(frac_label, gen)] = signals
    return data


def build_table(data: dict) -> str:
    """Build a summary table: fraction × generation × signal."""
    present_signals = set()
    for signals in data.values():
        present_signals.update(signals.keys())
    col_order = [s for s in ALL_SIGNALS if s in present_signals]
    extra = sorted(present_signals - set(ALL_SIGNALS))
    col_order.extend(extra)

    header = f"{'frac':<6} {'gen':<4} " + " ".join(f"{s:>18}" for s in col_order)
    lines = [header, "-" * len(header)]
    for frac_label in FRACTIONS:
        for gen in GENERATIONS:
            key = (frac_label, gen)
            if key not in data:
                continue
            vals = data[key]
            row = f"{frac_label:<6} gen{gen:<3} "
            row += " ".join(f"{vals.get(s, float('nan')):>18.6f}" for s in col_order)
            lines.append(row)
    return "\n".join(lines)


def compute_cross_fraction_rho(data: dict) -> dict:
    """For each signal and each generation, correlate signal value with fraction severity."""
    results = {}
    for sig in ALL_SIGNALS:
        rhos_per_gen = []
        for gen in GENERATIONS:
            severities = []
            values = []
            for frac_label, frac_val in FRACTIONS.items():
                key = (frac_label, gen)
                if key in data and sig in data[key]:
                    severities.append(frac_val)
                    values.append(data[key][sig])
            if len(severities) >= 3:
                rho, pval = spearmanr(severities, values)
                rhos_per_gen.append((gen, rho, pval))
        if rhos_per_gen:
            avg_rho = np.mean([abs(r) for _, r, _ in rhos_per_gen])
            results[sig] = {
                "per_gen": rhos_per_gen,
                "avg_abs_rho": avg_rho,
            }
    return results


def compute_cross_generation_rho(data: dict, frac_label: str = "100pct") -> dict:
    """For 100% fraction, correlate signal value with generation number."""
    results = {}
    for sig in ALL_SIGNALS:
        gens = []
        values = []
        for gen in GENERATIONS:
            key = (frac_label, gen)
            if key in data and sig in data[key]:
                gens.append(gen)
                values.append(data[key][sig])
        if len(gens) >= 3:
            rho, pval = spearmanr(gens, values)
            results[sig] = {"rho": rho, "pval": pval, "n": len(gens)}
    return results


def judge_mvp(cross_frac: dict, cross_gen: dict) -> tuple:
    """Determine PASS / CONDITIONAL / CONDITIONAL-RECHECK."""
    family_pass = {}
    details = {}
    for fam_name, fam_signals in SIGNAL_FAMILIES.items():
        best_rho_frac = 0.0
        best_rho_gen = 0.0
        best_sig_frac = None
        best_sig_gen = None
        for sig in fam_signals:
            if sig in cross_frac:
                r = cross_frac[sig]["avg_abs_rho"]
                if r > best_rho_frac:
                    best_rho_frac = r
                    best_sig_frac = sig
            if sig in cross_gen:
                r = abs(cross_gen[sig]["rho"])
                if r > best_rho_gen:
                    best_rho_gen = r
                    best_sig_gen = sig
        passed = best_rho_frac > RHO_THRESHOLD or best_rho_gen > RHO_THRESHOLD
        family_pass[fam_name] = passed
        details[fam_name] = {
            "passed": passed,
            "best_cross_frac": (best_sig_frac, best_rho_frac),
            "best_cross_gen": (best_sig_gen, best_rho_gen),
        }

    n_pass = sum(family_pass.values())
    if n_pass >= 2:
        verdict = "PASS"
    elif n_pass == 1:
        verdict = "CONDITIONAL"
    else:
        verdict = "CONDITIONAL-RECHECK"
    return verdict, n_pass, details


def main():
    parser = argparse.ArgumentParser(description="MVP Gate Check for collapse_severity_monitor")
    parser.add_argument("--output-dir", default="outputs",
                        help="Directory containing signals_*.jsonl files (default: outputs)")
    args = parser.parse_args()

    output_dir = args.output_dir
    if not os.path.isdir(output_dir):
        print(f"ERROR: output directory not found: {output_dir}", file=sys.stderr)
        sys.exit(1)

    print("=" * 80)
    print("MVP GATE CHECK — collapse_severity_monitor")
    print("=" * 80)

    data = load_signals(output_dir)
    print(f"\nLoaded {len(data)} file(s) across {len(set(f for f,g in data))} fractions, "
          f"{len(set(g for f,g in data))} generations\n")

    # Summary table
    print("SIGNAL VALUES (end-of-generation)")
    print("-" * 40)
    print(build_table(data))
    print()

    # Cross-fraction Spearman
    cross_frac = compute_cross_fraction_rho(data)
    print("CROSS-FRACTION Spearman ρ (severity=fraction, per generation then averaged)")
    print("-" * 40)
    for sig, res in cross_frac.items():
        mark = "✓" if res["avg_abs_rho"] > RHO_THRESHOLD else "✗"
        print(f"  {sig:<20s}  avg|ρ|={res['avg_abs_rho']:.4f}  {mark}")
        for gen, rho, pval in res["per_gen"]:
            print(f"    gen{gen}: ρ={rho:+.4f}  p={pval:.4f}")
    print()

    # Cross-generation Spearman (100% fraction)
    cross_gen = compute_cross_generation_rho(data)
    print("CROSS-GENERATION Spearman ρ (100pct, severity=generation)")
    print("-" * 40)
    for sig, res in cross_gen.items():
        mark = "✓" if abs(res["rho"]) > RHO_THRESHOLD else "✗"
        print(f"  {sig:<20s}  ρ={res['rho']:+.4f}  p={res['pval']:.4f}  n={res['n']}  {mark}")
    print()

    # MVP Verdict
    verdict, n_pass, details = judge_mvp(cross_frac, cross_gen)
    print("=" * 80)
    print(f"MVP VERDICT: {verdict}  ({n_pass}/3 families passed)")
    print("=" * 80)
    for fam, d in details.items():
        status = "PASS" if d["passed"] else "FAIL"
        sig_f, rho_f = d["best_cross_frac"]
        sig_g, rho_g = d["best_cross_gen"]
        print(f"  {fam:<12s} [{status}]  "
              f"best_frac: {sig_f or 'N/A'} |ρ|={rho_f:.4f}  "
              f"best_gen: {sig_g or 'N/A'} |ρ|={rho_g:.4f}")
    print()


if __name__ == "__main__":
    main()

